class Solution {
    fun numSplits(text:String):Int{
        val n=text.length;
        val left=IntArray(n);
        val right=IntArray(n);
        var count=IntArray(26);
        var distinct=0;
        for(i in text.indices){
            if(count[text[i]-'a']++==0)distinct++;
            left[i]=distinct
        };
        count=IntArray(26);
        distinct=0;
        for(i in text.lastIndex downTo 0){
            if(count[text[i]-'a']++==0)distinct++;
            right[i]=distinct
        };
        return (0 until n-1).count{
            left[it]==right[it+1]
        }
    }
}

